insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('17e5ea51-94a8-4084-bfd8-18b8a92f9ae9', 'ja', '昼間に声をかけられるとき、女性が嫌がるのは何ですか？', '["公共の場で、知らない人に声をかけられること", "用事や日課を、男性にさえぎられること", "昼間に、恋愛的な意図をストレートに伝えられること", "心地よさと敬意を無視した声のかけ方"]'::jsonb, '不快感は、声をかけられることそのものではなく、境界線を無視されることから生まれます。')
