insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5c7c4962-c5cf-480e-94ba-1cc03443f821', 'ja', '店で本を見ている女性に気づきます。心地よさを生む声のかけ方は、どれですか？', '["後ろから近づいて、肩に触れる", "すぐに見た目を褒める", "彼女が先にこちらを見るのを待つ", "彼女の視界に入り、落ち着いてほほえんでから、「こんにちは」と言う"]'::jsonb, '見える位置から笑顔で近づくことは、敬意を伝え、驚かせることを減らします。')
