insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4f1937b7-4e35-4007-97d7-0ba51bfa30af', 'ja', '夜の場では、なぜためらいが不利に働くのですか？', '["女性は絶えず声をかけられていて、選択肢が多いから", "騒がしい店では注意がすぐに移り、きっかけがすぐに消えるから", "お酒は人を短気にし、寛容さを失わせるから", "すぐに動かなければ、ほかの男性が彼女に声をかけるから"]'::jsonb, '夜の環境は変化が速いので、遅れるとサインが「逃したチャンス」に変わります。')
