insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e4f60ca8-4125-463e-b6ce-3c84259813a8', 'ja', '彼女がバーカウンターで注文しています。自分も注文するために隣に立ちます。彼女がこちらをちらりと見ます。どう動きますか？', '["先に自分の飲み物を注文し、二人とも飲み物を手にしてから話しかける", "彼女がもう一度サインを出すか、様子を見る", "「こんばんは」と言って、話し始める"]'::jsonb, 'それ以上のサインを待ってはいけません。夜は、ちらりと見られただけで、始めるには十分です。')
