insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('dbc9b59e-d2c5-4cb0-be94-f4bc54ea2bca', 'ja', 'グループに最初に話しかけるとき、目指すことは何ですか？', '["ほかの男性より目立つように、気になる女性を感心させる", "全員に受け入れられてから、彼女に注意を向ける", "承認を得るために、グループの中心人物を見つけて仲良くなる", "グループのほうから誘ってくるほどの価値を生み出す"]'::jsonb, 'グループ全体に気を配ることが、「その場にいていい」という許可を生みます。一人に絞る前に、全員を巻き込みましょう。')
