insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('10add83c-809f-43e0-aa9a-31d38bfb3270', 'ja', 'グループが大きな声で笑っています。そこへ、静かでまじめなひと言で話しかけます。何が起こりますか？', '["エネルギーのずれで、相手の関心が離れる", "深く関わってくれる", "飾らない姿勢を評価してくれる", "気になる女性が、こちらを脇へ連れ出す"]'::jsonb, 'エネルギーのずれは、相手の関心を離れさせます。流れを保つために、相手の盛り上がりに合わせましょう。')
