insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4756728e-4c07-484b-a976-9eeb5814eca7', 'ja', '「聞きたいことがあるんです」と話しかけます。彼女は期待するように顔を上げます。これは何を示していますか？', '["礼儀正しさ", "好奇心", "品定め", "拒絶"]'::jsonb, '好奇心が効くのは、自然に注意を引きつけるからです。興味をそそるひと言で始めましょう。')
