insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('28aa155d-35ca-4afd-abcc-bc4cb3e22a6d', 'ja', '「女性の意見を聞きたくて」という切り出し方は、なぜ効果的なのですか？', '["彼女が、このやり取りで大切にされ、重要だと感じられるから", "その悩みや質問が何なのか、好奇心が生まれるから", "上の両方"]'::jsonb, 'これが効くのは、彼女を「関係のある人」として位置づけるからです。最初から、自分も加わっていると感じてもらえます。')
